changeSet.sql:
CREATE SEQUENCE IF NOT EXISTS account_details_history_seq START WITH 1 INCREMENT BY 1 NO MINVALUE NO MAXVALUE CACHE 1;
CREATE TABLE IF NOT EXISTS account_details_history ( id BIGINT PRIMARY KEY DEFAULT nextval('account_details_history_seq'), account_id BIGINT NOT NULL, creation_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, changed_by VARCHAR(255) NOT NULL, category VARCHAR(255) NOT NULL, previous_value JSONB NOT NULL, new_value JSONB NOT NULL, reason VARCHAR,
CONSTRAINT fk_account_details_history_account FOREIGN KEY (account_id) REFERENCES account(id) );
CREATE INDEX IF NOT EXISTS idx_account_details_history_account_id ON account_details_history(account_id);

changeSet.rollback:
DROP INDEX IF EXISTS idx_account_details_history_account_id;

DROP TABLE IF EXISTS account_details_history;

DROP SEQUENCE IF EXISTS account_details_history_seq;
